// abordagem recomendada
function processarEncomenda(itens) {
  const quantidadeDeItens = itens.length; // nunca muda depois de calculado
  let precoTotal = 0; // vai ser reatribuído no ciclo

  for (const item of itens) {
    precoTotal += item.preco;
  }

  return { quantidadeDeItens, precoTotal };
}

