// (a) const idade; idade = 20;
// Erro (SyntaxError): uma const tem de ser inicializada no momento da declaração.

// (b) let nome = "Rui"; nome = "Rui Silva";
// Válido: let permite reatribuição.
let nome = "Rui";
nome = "Rui Silva";

// (c) const PI = 3.14; PI = 3.1416;
// Erro (TypeError): não é possível reatribuir uma const.

// (d) var x = 1; var x = 2;
// Válido (mas desaconselhado): var permite redeclarar a mesma variável no mesmo âmbito.
var x = 1;
var x = 2;

// Programa pedido: idade incrementada 3 vezes
let idade = 0;
for (let i = 0; i < 3; i++) {
  idade++;
}
console.log(idade); // 3

const carrinho = ["pão", "leite"];

carrinho.push("ovos"); // adiciona sem reatribuir a variável
const indicePao = carrinho.indexOf("pão");
carrinho.splice(indicePao, 1); // remove "pão" sem reatribuir a variável

console.log(carrinho); // ["leite", "ovos"]

// carrinho = ["arroz"];
// TypeError: Assignment to constant variable.
// Falharia porque const fixa a referência guardada em carrinho ao array original;
// atribuir um array novo, mesmo com conteúdo diferente, tentaria mudar essa referência.

function testarAmbitos() {
  for (let contador = 0; contador < 5; contador++) {
    var ultimoValor = contador;
  }

  console.log(ultimoValor); // 4
  // Funciona porque var não respeita o âmbito do bloco do for;
  // ultimoValor pertence ao âmbito da função testarAmbitos inteira.

  {
    let valorIsolado = 99;
    console.log(valorIsolado); // 99, acessível dentro do bloco
  }

  // console.log(valorIsolado);
  // ReferenceError: valorIsolado is not defined.
  // let respeita o âmbito de bloco, por isso a variável deixa de existir
  // fora das chavetas onde foi declarada, ao contrário do que acontece com var.
}

testarAmbitos();
